let lang='en',plan={},category='',query='',view='discover',storageOK=true,guideState={step:0,need:'',zip:'35896',schedule:'any',selected:[]};
try{lang=localStorage.getItem('cb-lang')==='es'?'es':'en';const p=JSON.parse(localStorage.getItem('cb-plan')||'{}');for(const r of resources)if(Array.isArray(p[r.id]))plan[r.id]=r.steps.map((_,i)=>Boolean(p[r.id][i]));}catch{storageOK=false;}
function persist(){try{localStorage.setItem('cb-plan',JSON.stringify(plan));localStorage.setItem('cb-lang',lang)}catch{storageOK=false;toast(t('Storage is unavailable. Keep this page open or print your plan.','No hay almacenamiento. Mantén la página abierta o imprime tu plan.'))}}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function norm(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
const searchAliases={groceries:'food pantry',ride:'transport bus',wifi:'internet computer',resume:'job career',rent:'housing tenant',doctor:'health clinic',anxiety:'mental counseling',tutor:'homework education',ropa:'clothing clothes',abogado:'legal lawyer',tarea:'homework tutoring',comida:'food pantry',trabajo:'job career',mayores:'senior aging'};
function matchScore(r,q){let tokens=norm(q).split(/\W+/).filter(x=>x.length>2&&!['need','help','with','have','that','the','and','for','can','get','not','dont','some','want','necesito','ayuda','para','tengo','con','una','los','las','que','pero','sin'].includes(x));tokens=[...new Set(tokens.flatMap(x=>[x,...(searchAliases[x]||'').split(' ')]).filter(Boolean))];const name=norm(r.name+' '+r.esname),terms=norm(r.terms),desc=norm(r.desc+' '+r.esdesc);return tokens.reduce((a,x)=>a+(name.includes(x)?4:terms.includes(x)?3:desc.includes(x)?1:0),0)}
function matches(r,q){return matchScore(r,q)>0}

function renderLanguage(){document.documentElement.lang=lang;$$('[data-i]').forEach(e=>e.innerHTML=words[lang][e.dataset.i]);$$('[data-ph]').forEach(e=>e.placeholder=words[lang][e.dataset.ph]);$('#language').innerHTML=lang==='es'?'◎ EN / <strong>ES</strong>':'◎ <strong>EN</strong> / ES';$('#language').setAttribute('aria-label',t('Switch to Spanish','Cambiar a inglés'));renderCategories();renderResources();renderPlan();$('#sort-label').textContent=t('Sort by','Ordenar por');$('#sort option[value=relevance]').textContent=t('Recommended','Recomendados');$('#sort option[value=name]').textContent=t('Name A–Z','Nombre A–Z');$('#saved-label').textContent=t('Saved only','Solo guardados');$('#try-label').textContent=t('Try searching:','Prueba buscar:');}
function renderCategories(){$('#categories').innerHTML=cats.map(([id,en,es])=>`<button class="category ${category===id?'active':''}" data-cat="${id}" aria-pressed="${category===id}"><span class="icon">${svg(id)}</span><span>${t(en,es)}<small>${resources.filter(r=>r.cat===id).length} ${resources.filter(r=>r.cat===id).length===1?t('resource','recurso'):t('resources','recursos')}</small></span></button>`).join('');}
function renderResources(){let list=resources.filter(r=>(!category||r.cat===category)&&(!query||matches(r,query))&&(!$('#saved-only')?.checked||plan[r.id]));if($('#sort')?.value==='name')list.sort((a,b)=>t(a.name,a.esname).localeCompare(t(b.name,b.esname)));else if(query)list.sort((a,b)=>matchScore(b,query)-matchScore(a,query));$('#results-title').textContent=query?t('Support for your search','Apoyo para tu búsqueda'):category?t(cats.find(c=>c[0]===category)[1],cats.find(c=>c[0]===category)[2]):t('A few good places to start','Buenos lugares para empezar');$('#result-count').textContent=t(`${list.length} ${list.length===1?'resource':'resources'}`,`${list.length} ${list.length===1?'recurso':'recursos'}`);$('#resource-grid').innerHTML=list.length?list.map(r=>`<article class="resource"><div class="cardtop"><span class="icon">${svg(r.cat)}</span><button class="save ${plan[r.id]?'saved':''}" data-save="${r.id}" aria-label="${escapeHTML(t(plan[r.id]?'Remove from plan':'Save to plan',plan[r.id]?'Quitar del plan':'Guardar en el plan'))}: ${escapeHTML(r.name)}" aria-pressed="${!!plan[r.id]}">${plan[r.id]?'♥':'♡'}</button></div><span class="tag">${t(cats.find(c=>c[0]===r.cat)[1],cats.find(c=>c[0]===r.cat)[2])}</span><h3>${t(r.name,r.esname)}</h3><p>${t(r.desc,r.esdesc)}</p><div class="cardfoot"><small>⌖ ${t(r.area,r.esarea)}</small><button data-detail="${r.id}">${t('View next steps ↗','Ver próximos pasos ↗')}</button></div></article>`).join(''):`<div class="empty"><h2>${t('Let’s find another path.','Busquemos otro camino.')}</h2><p>${t('This pilot has a small resource list. Try a category, use the guided assessment, or reach a person at 211.','Este piloto tiene una lista pequeña. Prueba una categoría, usa la guía o contacta al 211.')}</p><button class="primary" data-guide>${t('Get guided support ↗','Buscar apoyo guiado ↗')}</button> <a class="outline" href="tel:211">${t('Call 211','Llamar al 211')}</a></div>`;$('#plan-count').textContent=Object.keys(plan).length;}
function renderPlan(){const saved=resources.filter(r=>plan[r.id]);const total=saved.length*3,done=saved.reduce((a,r)=>a+plan[r.id].filter(Boolean).length,0);$('#progress-text').textContent=t(`${done} of ${total} steps complete`,`${done} de ${total} pasos completados`);$('#progress').style.width=(total?done/total*100:0)+'%';$('#plan-list').innerHTML=saved.length?saved.map(r=>`<article class="planresource"><div class="planhead"><h3>${t(r.name,r.esname)}</h3><button class="textbutton" data-save="${r.id}">${t('Remove ×','Quitar ×')}</button></div><div class="tasks">${t(r.steps,r.essteps).map((s,i)=>`<label class="${plan[r.id][i]?'done':''}"><input type="checkbox" data-task="${r.id}:${i}" ${plan[r.id][i]?'checked':''}><span>${s}</span></label>`).join('')}</div><a class="outline small" href="${r.url}" target="_blank" rel="noopener">${t('Open official source ↗','Abrir fuente oficial ↗')}</a></article>`).join(''):`<div class="empty"><h2>${t('Your next chapter starts here.','Tu nueva etapa empieza aquí.')}</h2><p>${t('Save a resource with the heart button, or build a plan with the guided assessment.','Guarda un recurso con el corazón o crea un plan con la guía.')}</p><button class="primary" data-guide>${t('Build my plan ↗','Crear mi plan ↗')}</button></div>`;$('#calendar').disabled=!saved.length;$('#print').disabled=!saved.length;$('#clearplan').hidden=!saved.length;}
function setView(v){view=v;$$('.page').forEach(e=>e.classList.toggle('hidden',e.id!==v));$$('[data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===v));renderPlan();window.scrollTo({top:0,behavior:'smooth'});}
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function toggleSave(id){if(plan[id])delete plan[id];else plan[id]=[false,false,false];persist();renderResources();renderPlan();toast(t(plan[id]?'Added to your plan':'Removed from your plan',plan[id]?'Añadido a tu plan':'Eliminado de tu plan'))}
function modal(content){$('#modalcontent').innerHTML=content;if(!$('#modal').open)$('#modal').showModal();$('#modalcontent').scrollTop=0;}
function close(){$('#modal').close()}
function detail(id){const r=resources.find(r=>r.id===id);modal(`<span class="modaleyebrow">${t('LOCAL SUPPORT · OFFICIAL SOURCE','APOYO LOCAL · FUENTE OFICIAL')}</span><h2 class="modal-title">${t(r.name,r.esname)}</h2><p class="modalcopy">${t(r.desc,r.esdesc)}</p><h3>${t('What to know','Qué debes saber')}</h3><p class="modalcopy">${t(r.elig,r.eselig)}</p><h3>${t('Your next steps','Tus próximos pasos')}</h3><ol class="modalcopy">${t(r.steps,r.essteps).map(s=>`<li>${s}</li>`).join('')}</ol><p class="hint">${t('Official source reviewed '+(r.reviewed||'2026-10-14')+'. Confirm details directly with the provider.','Fuente oficial revisada el '+(r.reviewed||'2026-10-14')+'. Confirma los detalles con el proveedor.')}</p><div class="modalactions"><button class="outline" id="detail-save">${t(plan[id]?'Saved to plan ✓':'Save to my plan',plan[id]?'Guardado ✓':'Guardar en mi plan')}</button><a class="primary" href="${r.url}" target="_blank" rel="noopener">${t('Official website ↗','Página oficial ↗')}</a></div>${r.phone?'<p><a href="tel:211">'+t('Call 211 ↗','Llamar al 211 ↗')+'</a></p>':''}`);$('#detail-save').onclick=()=>{if(!plan[id])toggleSave(id);$('#detail-save').textContent=t('Saved to plan ✓','Guardado ✓')};}
function startGuide(){guideState={step:0,need:'',zip:'35896',schedule:'any',selected:[]};guide()}
function guide(){const s=guideState;const stepbar=`<div class="steps">${[0,1,2].map(i=>`<i class="${i<=s.step?'on':''}"></i>`).join('')}</div>`;if(s.step===0){modal(`${stepbar}<span class="modaleyebrow">${t('STEP 1 OF 3 · TELL US A LITTLE','PASO 1 DE 3 · CUÉNTANOS UN POCO')}</span><h2 class="modal-title">${t('What’s on your mind?','¿Qué necesitas?')}</h2><p class="modalcopy">${t('You don’t need to know a program name. Describe what would help you right now.','No necesitas saber el nombre de un programa. Describe qué te ayudaría ahora.')}</p><form id="guide-form"><label class="field">${t('I could use help with…','Me vendría bien ayuda con…')}<textarea id="need-input" required maxlength="800" placeholder="${t('Example: I need groceries and a ride to work.','Ejemplo: Necesito comida y transporte al trabajo.')}">${escapeHTML(s.need)}</textarea></label><div class="chips"><button type="button" class="chip" data-sample="food">${t('Food & a ride','Comida y transporte')}</button><button type="button" class="chip" data-sample="jobs">${t('Work & skills','Empleo y habilidades')}</button><button type="button" class="chip" data-sample="housing">${t('Rent & bills','Alquiler y facturas')}</button></div><p class="hint">${t('You can use live AI in the next step. Please leave out names, account numbers, and sensitive details.','Puedes usar IA en vivo en el próximo paso. No incluyas nombres, números de cuenta ni datos sensibles.')}</p><div class="modalactions"><button type="button" class="textbutton" id="example">${t('Try a sample story','Probar un ejemplo')}</button><button class="primary" type="submit">${t('Continue ↗','Continuar ↗')}</button></div></form>`);$('#guide-form').onsubmit=e=>{e.preventDefault();s.need=$('#need-input').value.trim();if(!s.need)return;s.step=1;guide()};$$('[data-sample]').forEach(b=>b.onclick=()=>{$('#need-input').value=b.dataset.sample==='food'?t('I need affordable groceries and transportation to work.','Necesito comida económica y transporte al trabajo.'):b.dataset.sample==='jobs'?t('I need a job and computer skills to improve my résumé.','Necesito empleo y habilidades de computación para mejorar mi currículum.'):t('I need help with rent and electricity bills.','Necesito ayuda con el alquiler y las facturas de luz.')});$('#example').onclick=()=>{$('#need-input').value=t('I work early mornings, don’t have a car, and need affordable groceries.','Trabajo temprano, no tengo carro y necesito comida económica.')}}else if(s.step===1){modal(`${stepbar}<span class="modaleyebrow">${t('STEP 2 OF 3 · MAKE IT PRACTICAL','PASO 2 DE 3 · HAGÁMOSLO PRÁCTICO')}</span><h2 class="modal-title">${t('Let’s fit this to your day.','Adaptemos esto a tu día.')}</h2><form id="context-form"><label class="field">${t('ZIP code','Código postal')}<input id="zip" inputmode="numeric" pattern="[0-9]{5}" maxlength="5" value="${escapeHTML(s.zip)}" required></label><label class="field">${t('When is it easiest to take your next step?','¿Cuándo puedes dar tu próximo paso?')}<select id="schedule"><option value="any">${t('My schedule is flexible','Mi horario es flexible')}</option><option value="morning">${t('Before work / early mornings','Antes del trabajo / temprano')}</option><option value="afternoon">${t('Afternoons','Por la tarde')}</option><option value="weekend">${t('Weekends','Fines de semana')}</option></select></label><label class="ai-choice"><input id="use-ai" type="checkbox" checked><span>${t('Use live AI to understand my needs','Usar IA en vivo para entender mis necesidades')}<small>${t('Your description, ZIP, schedule, and language will be sent to OpenAI when you continue. You can uncheck this for matching on your device.','Tu descripción, código postal, horario e idioma se enviarán a OpenAI al continuar. Desmarca para buscar en tu dispositivo.')}</small></span></label><p class="hint">${t('This pilot covers Huntsville and North Alabama. Your ZIP provides context; results are not distance-ranked. We cannot confirm opening hours or availability.','Este piloto cubre Huntsville y el norte de Alabama. El código da contexto; no ordenamos por distancia ni confirmamos horarios o disponibilidad.')}</p><div class="modalactions"><button type="button" class="textbutton" id="back">${t('← Back','← Atrás')}</button><button class="primary" type="submit">${t('Find my next steps ↗','Buscar mis próximos pasos ↗')}</button></div></form>`);$('#schedule').value=s.schedule;$('#back').onclick=()=>{s.step=0;guide()};$('#context-form').onsubmit=async e=>{e.preventDefault();s.zip=$('#zip').value;s.schedule=$('#schedule').value;s.selected=resources.filter(r=>matches(r,s.need)).map(r=>r.id);if(!s.selected.length)s.selected=['housing211','family211'];s.ai=null;s.aiError='';if($('#use-ai').checked){const submit=$('#context-form button[type=submit]');submit.disabled=true;submit.textContent=t('Finding your next steps…','Buscando tus próximos pasos…');try{const response=await fetch(location.origin==='https://framber-rodriguez.github.io'?'https://community-bridge-huntsville.bframber12.chatgpt.site/api/assist':'/api/assist',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({need:s.need,zip:s.zip,schedule:s.schedule,language:lang}),signal:AbortSignal.timeout(30000)});const data=await response.json();if(!response.ok)throw Error(data.code||'ai_unavailable');if(data.mode!=='live-ai'||!Array.isArray(data.recommendations))throw Error('ai_unavailable');s.ai=data;s.selected=data.recommendations.map(r=>r.id).filter(id=>resources.some(r=>r.id===id));if(!s.selected.length)s.selected=['housing211'];}catch(error){s.aiError=error.message;}}if(!$('#modal').open)return;s.step=2;guide()}}else{const rec=resources.filter(r=>s.selected.includes(r.id));modal(`${stepbar}<span class="modaleyebrow">${t('STEP 3 OF 3 · A WAY FORWARD','PASO 3 DE 3 · UN CAMINO ADELANTE')}</span>${s.ai?`<div class="ai-result"><strong>✳ ${t('Live AI · Based on reviewed resources','IA en vivo · Basada en recursos revisados')}</strong><p>${escapeHTML(s.ai.summary)}</p></div>`:s.aiError?`<div class="warning">${s.aiError==='ai_billing_required'?t('Live AI is connected but the service needs API credits. These suggestions use keyword matching on this device.','La IA está conectada, pero el servicio necesita créditos de API. Estas sugerencias usan palabras clave en este dispositivo.'):t('Live AI is temporarily unavailable. These suggestions use keyword matching on this device.','La IA no está disponible temporalmente. Estas sugerencias usan palabras clave en este dispositivo.')}</div>`:`<span class="hint">${t('On-device keyword matching','Búsqueda por palabras clave en tu dispositivo')}</span>`}<h2 class="modal-title">${t('Here’s a place to start.','Aquí puedes empezar.')}</h2><p class="modalcopy">${t('These resources may help with the needs you described. Select the ones to include in your plan.','Estos recursos podrían ayudarte. Selecciona los que quieres incluir en tu plan.')}</p>${s.schedule!=='any'?`<div class="warning">${t('Your schedule matters. Contact each provider to confirm a time that works for you. Early-morning transit may not cover your start time.','Tu horario importa. Confirma una hora conveniente con cada organización. El transporte temprano podría no cubrir tu entrada al trabajo.')}</div>`:''}${!s.zip.startsWith('358')&&!s.zip.startsWith('357')?`<p class="warning">${t('Some results may be outside your area. Contact 211 for referrals that serve your ZIP.','Algunos resultados pueden estar fuera de tu zona. Contacta al 211 para referencias en tu código postal.')}</p>`:''}${rec.map(r=>`<div class="matchcard"><label><input type="checkbox" data-choose="${r.id}" checked><span><strong>${t(r.name,r.esname)}</strong><small>${t(r.area,r.esarea)}</small>${s.ai?`<p class="match-reason">${escapeHTML(s.ai.recommendations.find(x=>x.id===r.id)?.reason||'')}</p>`:''}</span></label></div>`).join('')}${s.ai?.caution?`<p class="warning">${escapeHTML(s.ai.caution)}</p>`:''}<p class="hint">${t('Matches are suggestions, not eligibility decisions. Your story is not saved. Checklist items stay on this device.','Son sugerencias, no decisiones de elegibilidad. Tu descripción no se guarda. Las tareas se guardan en este dispositivo.')}</p><div class="modalactions"><button class="textbutton" id="back">${t('← Back','← Atrás')}</button><button class="primary" id="finish">${t('Save my action plan ↗','Guardar mi plan ↗')}</button></div>`);$('#back').onclick=()=>{s.step=1;guide()};$('#finish').onclick=()=>{const ids=$$('[data-choose]:checked').map(e=>e.dataset.choose);if(!ids.length){toast(t('Select at least one resource.','Selecciona al menos un recurso.'));return}ids.forEach(id=>{if(!plan[id])plan[id]=[false,false,false]});persist();renderResources();close();setView('plan');toast(t('Your next steps are ready.','Tus próximos pasos están listos.'));guideState.need=''}}}
function download(text,name,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function calendar(){const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);const date=tomorrow.getFullYear()+'-'+String(tomorrow.getMonth()+1).padStart(2,'0')+'-'+String(tomorrow.getDate()).padStart(2,'0');modal(`<span class="modaleyebrow">${t('ONE SMALL STEP','UN PEQUEÑO PASO')}</span><h2 class="modal-title">${t('Make time for your next step.','Haz tiempo para tu próximo paso.')}</h2><form id="reminderform"><label class="field">${t('Reminder date','Fecha')}<input type="date" id="reminderdate" required value="${date}"></label><p class="hint">${t('Download a calendar event and import it into your calendar. A reminder is only active after you add it. No messages are sent by this pilot.','Descarga e importa el evento en tu calendario. El recordatorio se activa después de añadirlo. Este piloto no envía mensajes.')}</p><button class="primary" type="submit">${t('Download calendar reminder ↗','Descargar recordatorio ↗')}</button></form>`);$('#reminderform').onsubmit=e=>{e.preventDefault();const d=$('#reminderdate').value.replaceAll('-','');const dt=new Date($('#reminderdate').value+'T12:00:00');dt.setDate(dt.getDate()+1);const end=dt.getFullYear()+String(dt.getMonth()+1).padStart(2,'0')+String(dt.getDate()).padStart(2,'0');const txt=resources.filter(r=>plan[r.id]).map(r=>t(r.name,r.esname)+' - '+r.url).join('\n');const esc=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');download(['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Community Bridge//Action Plan//EN','BEGIN:VEVENT','UID:'+Date.now()+'@communitybridge','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z'),'DTSTART;VALUE=DATE:'+d,'DTEND;VALUE=DATE:'+end,'SUMMARY:'+t('Community Bridge: take your next step','Community Bridge: da tu próximo paso'),'DESCRIPTION:'+esc(txt),'BEGIN:VALARM','TRIGGER:-PT9H','ACTION:DISPLAY','DESCRIPTION:Community Bridge','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n'),'community-bridge-reminder.ics','text/calendar');close();toast(t('Downloaded. Import it into your calendar.','Descargado. Impórtalo en tu calendario.'))};}
function suggestion(){modal(`<span class="modaleyebrow">${t('HELP THE BRIDGE GROW','AYUDA A CRECER')}</span><h2 class="modal-title">${t('Share a helpful resource.','Comparte un recurso útil.')}</h2><form id="suggestform"><label class="field">${t('Organization name','Nombre de organización')}<input id="org" required maxlength="120"></label><label class="field">${t('Official website','Página oficial')}<input id="orgurl" type="url" required placeholder="https://"></label><label class="field">${t('What does it help with?','¿Con qué ayuda?')}<textarea id="orgnotes" required maxlength="700"></textarea></label><p class="hint">${t('This downloads a suggestion file you can share with the team. Nothing is submitted or added to the directory automatically.','Descarga un archivo para compartir con el equipo. No se envía ni publica automáticamente.')}</p><button class="primary" type="submit">${t('Download suggestion ↗','Descargar sugerencia ↗')}</button></form>`);$('#suggestform').onsubmit=e=>{e.preventDefault();download(JSON.stringify({organization:$('#org').value,website:$('#orgurl').value,description:$('#orgnotes').value,status:'unreviewed suggestion'},null,2),'community-bridge-resource-suggestion.json','application/json');close();toast(t('Suggestion downloaded.','Sugerencia descargada.'))}}
let slide=0;const slides=[{en:['A little help. A way forward.','Community Bridge makes local support easier to find and easier to act on.','For students, staff, families, seniors, and every neighbor.'],es:['Un poco de ayuda. Un camino adelante.','Community Bridge facilita encontrar apoyo local y dar el próximo paso.','Para estudiantes, empleados, familias, mayores y cada vecino.']},{en:['The barrier is the next step.','Support can be scattered across websites, forms, and unfamiliar program names.','Our goal: turn a need into a clear, practical plan.'],es:['La barrera es el próximo paso.','El apoyo puede estar disperso entre páginas, formularios y nombres desconocidos.','Nuestra meta: convertir una necesidad en un plan claro.']},{en:['Meet a neighbor.','“I work early mornings, don’t have a car, and need affordable groceries.”','Watch the live demo: describe → find support → save a checklist.'],es:['Conoce a un vecino.','«Trabajo temprano, no tengo carro y necesito comida económica».','Mira la demo: describir → encontrar apoyo → guardar tareas.']},{en:['A practical first version.','Official resource links • English & Spanish • Optional live AI','Saved checklists • Calendar downloads • Volunteer connections'],es:['Una primera versión práctica.','Fuentes oficiales • Inglés y español • IA opcional','Tareas guardadas • Calendario • Voluntariado']},{en:['Start local. Grow responsibly.','Next: provider-maintained listings and wider coverage.','Proposed impact measures: completed next steps, successful referrals, and time saved. No impact results claimed yet.'],es:['Empieza local. Crece con responsabilidad.','Próximamente: fichas actualizadas por proveedores y más cobertura.','Métricas propuestas: pasos completados, referencias útiles y tiempo ahorrado. Aún no hay resultados de impacto.']}];
function pitch(){const a=slides[slide][lang];modal(`<span class="modaleyebrow">COMMUNITY BRIDGE · ${t('OUR STORY','NUESTRA IDEA')}</span><div class="pitch-number">0${slide+1}</div><h2 class="modal-title">${a[0]}</h2><div class="pitchpoints"><div>${a[1]}</div><div>${a[2]}</div></div><div class="modalactions"><button class="textbutton" id="prev" ${slide===0?'disabled':''}>${t('← Previous','← Anterior')}</button><span class="hint">${slide+1} / ${slides.length}</span><button class="primary" id="next">${t(slide===2?'Try the demo ↗':slide===4?'Explore the app ↗':'Next ↗',slide===2?'Probar demo ↗':slide===4?'Explorar ↗':'Siguiente ↗')}</button></div>${slide===2?'<button class="textbutton" id="skipdemo">'+t('Continue the story →','Continuar la idea →')+'</button>':''}`);$('#prev').onclick=()=>{slide--;pitch()};$('#next').onclick=()=>{if(slide===2){close();startGuide();$('#example').click()}else if(slide===4){close();setView('discover')}else{slide++;pitch()}};if($('#skipdemo'))$('#skipdemo').onclick=()=>{slide++;pitch()};}
function about(){modal(`<span class="modaleyebrow">${t('TRANSPARENT BY DESIGN','TRANSPARENCIA DESDE EL INICIO')}</span><h2 class="modal-title">${t('A working community pilot.','Un piloto comunitario funcional.')}</h2><p class="modalcopy">${t('Community Bridge brings official resource links, bilingual navigation, and personal checklists into one place. Optional live AI interprets your description using our reviewed resource list. If AI is unavailable, the app clearly switches to on-device keyword matching.','Community Bridge reúne fuentes oficiales, navegación bilingüe y tareas personales. La IA opcional interpreta tu descripción con nuestra lista revisada. Si no está disponible, la aplicación lo indica y usa palabras clave en tu dispositivo.')}</p><p class="modalcopy">${t('Resource information is reviewed manually. We do not confirm program eligibility, make applications, book rides, or send reminders. Saved plans stay on your device. Calendar files must be imported. Resource suggestions must be shared manually.','La información se revisa manualmente. No confirmamos elegibilidad, solicitamos programas, reservamos transporte ni enviamos recordatorios. Los planes se guardan en tu dispositivo. Debes importar los eventos y compartir sugerencias manualmente.')}</p><p class="modalcopy">${t('With live AI enabled, your description, ZIP, schedule, and language are sent to OpenAI. The app does not save your description and requests no stored model response. Provider data-handling policies still apply. Plans stay on your device. Next: provider updates and expansion to more communities.','Con IA activada, tu descripción, código postal, horario e idioma se envían a OpenAI. La aplicación no guarda tu descripción y solicita no almacenar la respuesta. Aplican las políticas de datos del proveedor. Próximamente: actualizaciones de organizaciones y más cobertura.')}</p><a class="primary" href="https://www.211connectsalabama.org/get-help/" target="_blank" rel="noopener">${t('Talk to a human through 211 ↗','Hablar con una persona en 211 ↗')}</a>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)setView(b.dataset.view);if(b.dataset.cat){category=category===b.dataset.cat?'':b.dataset.cat;renderCategories();renderResources()}if(b.dataset.save)toggleSave(b.dataset.save);if(b.dataset.detail)detail(b.dataset.detail);if(b.hasAttribute('data-guide'))startGuide()});
document.addEventListener('change',e=>{if(e.target.dataset.task){const [id,index]=e.target.dataset.task.split(':');plan[id][Number(index)]=e.target.checked;persist();renderPlan()}});
$('#searchform').onsubmit=e=>{e.preventDefault();query=$('#search').value.trim();renderResources()};$('#search').addEventListener('input',()=>{query=$('#search').value.trim();renderResources()});$('#reset').onclick=()=>{category='';query='';$('#search').value='';$('#saved-only').checked=false;$('#sort').value='relevance';renderCategories();renderResources()};$('#language').onclick=()=>{lang=lang==='en'?'es':'en';persist();close();renderLanguage()};$('#start').onclick=startGuide;$('#guided-bottom').onclick=startGuide;$('#browse').onclick=()=>$('#resources').scrollIntoView({behavior:'smooth'});$('#close-modal').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});$('#print').onclick=()=>window.print();$('#calendar').onclick=calendar;$('#suggest').onclick=suggestion;$('#pitch').onclick=()=>{slide=0;pitch()};$('#about').onclick=about;$$('.brand,.footerbrand').forEach(a=>a.onclick=e=>{e.preventDefault();setView('discover')});$('#clearplan').onclick=()=>{modal(`<h2 class="modal-title">${t('Clear your saved plan?','¿Borrar tu plan?')}</h2><p class="modalcopy">${t('This removes saved resources and completed tasks from this device.','Se eliminarán los recursos y tareas de este dispositivo.')}</p><div class="modalactions"><button class="outline" id="cancelclear">${t('Keep my plan','Conservar mi plan')}</button><button class="primary" id="confirmclear">${t('Clear plan','Borrar plan')}</button></div>`);$('#cancelclear').onclick=close;$('#confirmclear').onclick=()=>{plan={};persist();renderResources();renderPlan();close()}};
renderLanguage();

$('#sort').onchange=renderResources;$('#saved-only').onchange=renderResources;$$('[data-query]').forEach(b=>b.onclick=()=>{category='';query=t(b.dataset.query,b.dataset.esquery);$('#search').value=query;renderCategories();renderResources();$('#resources').scrollIntoView({behavior:'smooth'})});
